(501, NULL, NULL, NULL, 'insert', 'tasks', 436, '{\"team_id\":{\"from\":null,\"to\":3},\"work_order_id\":{\"from\":null,\"to\":1},\"recurring_task_id\":{\"from\":null,\"to\":2},\"title\":{\"from\":null,\"to\":\"N\\u00e1pov\\u011bda: (kopie)\"},\"description\":{\"from\":null,\"to\":\"Zde \\u00fakol vytvo\\u0159\\u00edte a p\\u0159i\\u0159ad\\u00edte ho n\\u011bkter\\u00e9mu z va\\u0161ich aktivn\\u00edch t\\u00fdm\\u016f. T\\u00edm p\\u0159en\\u00e1\\u0161\\u00edte zodpov\\u011bdnost za vykon\\u00e1n\\u00ed \\u00fakol\\u016f na konkr\\u00e9tn\\u00ed T\\u00fdm a lidi v n\\u011bm. Oni V\\u00e1m zp\\u011btn\\u011b prost\\u0159ednictv\\u00edm report\\u016f k \\u00fakol\\u016fm, vykazuj\\u00ed pr\\u00e1ci, \\u010das a najet\\u00e9 kilometry.\"},\"status\":{\"from\":null,\"to\":\"open\"},\"created_by_user_id\":{\"from\":null,\"to\":1},\"due_date\":{\"from\":null,\"to\":\"2026-09-19\"},\"task_type\":{\"from\":null,\"to\":\"recurring_instance\"},\"company_id\":{\"from\":null,\"to\":1}}', '52.4.140.84', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/83.0.4093.0 Safari/537.36 Edg/83.0.470.0', '2026-09-19 09:50:42'),
