(558, NULL, NULL, NULL, 'insert', 'tasks', 493, '{\"team_id\":{\"from\":null,\"to\":1},\"work_order_id\":{\"from\":null,\"to\":1},\"recurring_task_id\":{\"from\":null,\"to\":1},\"title\":{\"from\":null,\"to\":\"nainstalovat na web 2 (kopie)\"},\"description\":{\"from\":null,\"to\":\"Zde \\u00fakol vytvo\\u0159\\u00edte a p\\u0159i\\u0159ad\\u00edte ho n\\u011bkter\\u00e9mu z va\\u0161ich aktivn\\u00edch t\\u00fdm\\u016f. T\\u00edm p\\u0159en\\u00e1\\u0161\\u00edte zodpov\\u011bdnost za vykon\\u00e1n\\u00ed \\u00fakol\\u016f na konkr\\u00e9tn\\u00ed T\\u00fdm a lidi v n\\u011bm. Oni V\\u00e1m zp\\u011btn\\u011b prost\\u0159ednictv\\u00edm report\\u016f k \\u00fakol\\u016fm, vykazuj\\u00ed pr\\u00e1ci, \\u010das a najet\\u00e9 kilometry.\\r\\n\\r\\nN\\u00e1\\u0161 syst\\u00e9m je navr\\u017een tak, \\u017ee \\u00fakoly mohou vznikat jen tehdy, pat\\u0159\\u00ed-li n\\u011bjak\\u00e9 zak\\u00e1zce. \\u00dakol bez zak\\u00e1zky, ke kter\\u00e9 by pat\\u0159il, n\\u00e1m ned\\u00e1v\\u00e1 smysl.\"},\"status\":{\"from\":null,\"to\":\"open\"},\"created_by_user_id\":{\"from\":null,\"to\":1},\"due_date\":{\"from\":null,\"to\":\"2026-10-15\"},\"task_type\":{\"from\":null,\"to\":\"recurring_instance\"},\"company_id\":{\"from\":null,\"to\":1}}', '34.169.0.209', 'Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:129.0) Gecko/20100101 Firefox/129.0 Observatory/129.0', '2026-10-15 17:04:25'),
