INSERT INTO `tasks` (`id`, `company_id`, `team_id`, `work_order_id`, `due_date`, `task_type`, `recurring_task_id`, `generated_date`, `title`, `description`, `status`, `created_by_user_id`, `created_at`, `done_at`) VALUES
(1, 1, 1, 1, NULL, 'normal', NULL, '2026-04-14', 'nainstalovat na web', '', 'done', 1, '2026-04-14 00:23:23', '2026-04-14 00:59:13'),
(2, 1, 1, 1, NULL, 'normal', NULL, '2026-04-14', 'nainstalovat na web 2', 'Zde úkol vytvoříte a přiřadíte ho některému z vašich aktivních týmů. Tím přenášíte zodpovědnost za vykonání úkolů na konkrétní Tým a lidi v něm. Oni Vám zpětně prostřednictvím reportů k úkolům, vykazují práci, čas a najeté kilometry.', 'done', 1, '2026-04-14 00:56:12', '2026-04-14 00:58:50'),
(3, 1, 1, 1, '2026-04-15 00:00:00', 'recurring_master', 1, '2026-04-14', 'nainstalovat na web 2 (kopie)', 'Zde úkol vytvoříte a přiřadíte ho některému z vašich aktivních týmů. Tím přenášíte zodpovědnost za vykonání úkolů na konkrétní Tým a lidi v něm. Oni Vám zpětně prostřednictvím reportů k úkolům, vykazují práci, čas a najeté kilometry.\r\n\r\nNáš systém je navržen tak, že úkoly mohou vznikat jen tehdy, patří-li nějaké zakázce. Úkol bez zakázky, ke které by patřil, nám nedává smysl.', 'cancelled', 1, '2026-04-14 00:56:46', NULL),
(4, 2, 2, 2, NULL, 'normal', NULL, '2026-04-14', '#1: Přidejte svůj účet do Základního týmu', '\nVítejte v Bó systému.\n---------------------\n\nVaším prvním úkolem bude přidat sám sebe do **Základního týmu**.\n - Menu: Týmy > Aktivní > Karta: Základní tým > Upravit\n - v rozhraní můžete:\n  - sám sebe přidat a odebrat z týmu,\n  - změnit barvu týmu\n  - i jeho název\n - Až budete součástí týmu **Základní tým**, můžete napsat Report (nebo více) a tento úkol uzavřít.\n\nTip: Pokud nemůžete na Kartě úkolu najít tlačítko **Přidat Report**, nejste členem týmu, který má úkol na starosti.\n\nTip: Pokud v detailu úkolu nemůžete najít tlačítko **Uzavřít úkol**, tak k tomu úkolu nebyl napsán ani jeden Report.\n\n\n', 'open', 2, '2026-04-14 01:32:19', NULL),
(5, 2, 2, 2, NULL, 'normal', NULL, '2026-04-14', '#2: Pozvěte spolupracovníky', '\nMáte první tým, jste jeho členem, vytvořil jste první Report o splnění úkolu a možná jste i úkol označil jako Uzavřený.\n\nDalším Vaším úkolem bude přidat (pozvat) vaše spolupracovníky (pokud nějaké máte) do Bó systému:\n - Menu: Uživatelé > Přidat uživatele\n - Až budete hotovi, opět vypište Report a úkol ukončete.\n\nSystém funguje tak, že si volně můžete založit firmu v Bó systému. Spolupracovníkům potom vytváříte účty a tím je pozýváte do Bó systému.\n\n', 'open', 2, '2026-04-14 01:32:19', NULL),
(6, 1, 3, 1, NULL, 'normal', NULL, '2026-04-16', 'Nápověda:', 'Zde úkol vytvoříte a přiřadíte ho některému z vašich aktivních týmů. Tím přenášíte zodpovědnost za vykonání úkolů na konkrétní Tým a lidi v něm. Oni Vám zpětně prostřednictvím reportů k úkolům, vykazují práci, čas a najeté kilometry.', 'done', 1, '2026-04-16 01:21:46', '2026-04-16 23:47:24'),
(7, 1, 3, 1, '2026-04-16 00:00:00', 'recurring_master', 2, '2026-04-16', 'Nápověda: (kopie)', 'Zde úkol vytvoříte a přiřadíte ho některému z vašich aktivních týmů. Tím přenášíte zodpovědnost za vykonání úkolů na konkrétní Tým a lidi v něm. Oni Vám zpětně prostřednictvím reportů k úkolům, vykazují práci, čas a najeté kilometry.', 'cancelled', 1, '2026-04-16 01:23:38', NULL),
(8, 1, 1, 4, NULL, 'normal', NULL, '2026-04-20', 'Žijeme na planetě hmyzu 2', 'Žijeme na planetě hmyzu, který je majitelem planety a zřejmě řídí a vysává lidi. Však to znáte, komáři, mouchy.. mravenci... znepříjemní vám to hodně, když chtějí. Samozřejmě, nesmí se o tom mluvit, protože by se lidé zbláznili, poté, co by dlouho nevěřili. Leč... kniha Mariborská hypnóza, která vyhrála Magnesia litera, je přesně o tom. Tedy.. o mouchách, aspoň kam se to doposlouchal. A poslouchat ji v audio verzi je za trest, ještě navíc v noci, to je horor. Čapku, Havlíčku, Boženo.. vraťte se. Sion-fašisté, aktivní pomohači hmyzí civiliziace, nám unesli již i  literaturu. Film už dávno.\r\nBuď začneme napodobovat hmyz (třeba včely či mravenci se doslova nabízejí), těch, kterých je miliard krát víc, než nás, aspoň částečně, anebo bude naše civilizace znovu, již poněkolikáté, smetena. Již se hmyz adaptoval na vaše nové (spike) syntetické proteiny, které vám implantovala satanská vědecká sekta pomocí tzv. očkování proti tzv. covidu, co myslíte? Pro koho se ta výměna vlastně děla? Pro lidi až na posledním místě. Lidé jsou dělníci, námezní otroci. A jejich využitelnost pomalu končí. To, co zatím zvládlo tisíc lidí starého typu, zvládne jeden člověk s upgradovaným vědomím a schopnostmi, přibližně 50-100x geneticky poupravený (očkovaný).', 'open', 1, '2026-04-20 13:38:25', NULL),
(10, 1, 3, 4, '2026-04-23 00:00:00', 'recurring_master', 3, '2026-04-22', 'Žijeme na planetě hmyzu 2 (kopie)', 'Žijeme na planetě hmyzu, který je majitelem planety a zřejmě řídí a vysává lidi. Však to znáte, komáři, mouchy.. mravenci... znepříjemní vám to hodně, když chtějí. Samozřejmě, nesmí se o tom mluvit, protože by se lidé zbláznili, poté, co by dlouho nevěřili. Leč... kniha Mariborská hypnóza, která vyhrála Magnesia litera, je přesně o tom. Tedy.. o mouchách, aspoň kam se to doposlouchal. A poslouchat ji v audio verzi je za trest, ještě navíc v noci, to je horor. Čapku, Havlíčku, Boženo.. vraťte se. Sion-fašisté, aktivní pomohači hmyzí civiliziace, nám unesli již i  literaturu. Film už dávno.\r\nBuď začneme napodobovat hmyz (třeba včely či mravenci se doslova nabízejí), těch, kterých je miliard krát víc, než nás, aspoň částečně, anebo bude naše civilizace znovu, již poněkolikáté, smetena. Již se hmyz adaptoval na vaše nové (spike) syntetické proteiny, které vám implantovala satanská vědecká sekta pomocí tzv. očkování proti tzv. covidu, co myslíte? Pro koho se ta výměna vlastně děla? Pro lidi až na posledním místě. Lidé jsou dělníci, námezní otroci. A jejich využitelnost pomalu končí. To, co zatím zvládlo tisíc lidí starého typu, zvládne jeden člověk s upgradovaným vědomím a schopnostmi, přibližně 50-100x geneticky poupravený (očkovaný).', 'open', 1, '2026-04-22 00:49:06', NULL),
(11, 1, 3, 5, NULL, 'normal', NULL, '2026-04-23', 'Zahrada', 'Změřit plachtu na sklenik\r\n\r\nX Odvézt vozík bordel\r\n\r\nNákup\r\n- x travní osivo\r\n- x obrubníky 20ks 1m x15\r\n- x cement 5 pytlů\r\n- štěrk vozík\r\n- x zednická lžíce\r\n- objednané plachta na skleník\r\n- x prací prášek\r\n- zubní pasta\r\n- kartáček na zuby\r\n\r\n\r\nUdělat rozborku auta a zkusit opravit podlahu u spollujezdce', 'done', 1, '2026-04-23 17:09:15', '2026-04-25 00:42:29'),
