(60, 3, 272, 19, 5, 4, 1440, 'Revize provedena\r\nuklizena rozvodna, vysate a umyte rozvaděče.\r\nDále projitý celý provoz, očistěné rozvaděče, krabice, vypínače světla.\r\n\r\nVyměněn LED reflektor v přízemí svítící na čerpadlo v jímce, protože byl vadný (blikal)', 4, '2026-07-12 01:33:47', NULL),
(61, 3, 270, 18, 12, 4, 480, 'Nafasovaná další část materiálu, led trubice a žárovky, krabice,...\r\nVyměněno 7ks žárovek, \r\nOpraveny 3ks zářivkových svítidel, předělaná 1ks krabice z venecku na wago..', 4, '2026-07-13 12:10:17', NULL),
(62, 3, 270, 18, 0, 4, 60, 'Odvoz starých zářivek k likvidaci na firmě, předáno do skladů ', 4, '2026-07-13 13:00:09', NULL),
(63, 3, 270, 18, 10, 4, 960, 'Hledání a popisování vývodů z rozvaděče RS1 a RS2\r\n\r\nDoplnění chybějících víček na krabice\r\n\r\nKontrola a oprava uvolněnch zásuvek v 1np a 2.np\r\n\r\n', 4, '2026-07-15 13:26:27', NULL),
(64, 3, 270, 18, 0, 4, 480, 'Šatny\r\n=====\r\nMontáž 3ks OBO krabic na neukončené vývody\r\n\r\nGaráž\r\n=====\r\nMontáž  1 ks OBO krabice na neukončený vývod\r\n\r\nMontáž 1ks krabice 20x30cm na 4 neukončené vývody\r\n', 4, '2026-07-15 13:29:42', NULL),
(65, 3, 269, 10, 0, 4, 30, 'Provedeno', 4, '2026-07-15 13:30:30', NULL),
(66, 3, 252, 10, 0, 4, 30, 'Provedeno', 4, '2026-07-15 13:31:18', NULL),
(67, 3, 253, 17, 5, 4, 120, 'Provedena údržba, vyčistěno, namazáno\r\n\r\nodběry: 0,6 - 0,8A\r\n\r\nElmer: 5100072735\r\n\r\nStav:545kwh', 4, '2026-07-15 13:36:26', NULL),
(68, 3, 293, 10, 0, 4, 60, 'hotovo', 4, '2026-07-17 12:43:56', NULL),
(69, 3, 292, 17, 10, 4, 0, 'Vyčistěná,namazaná, \r\n\r\nnutno vykosit!\r\n\r\nProud: 13A\r\n\r\nVapětí: 14V\r\n\r\nElmer: 1880091198\r\n\r\nStav: 10215kwh\r\n\r\n', 4, '2026-07-17 12:48:59', NULL),
(70, 3, 292, 17, 0, 4, 120, 'Zapomněl jsem napsat lidi:', 4, '2026-07-17 12:49:39', NULL),
(71, 3, 291, 17, 5, 4, 120, 'Vyčistěno, namazáno\r\n\r\nProud: 8,9A\r\n\r\nNapětí: 7,2V\r\n\r\nElmer: 1021217830\r\n\r\nStav: 17656', 4, '2026-07-17 12:52:34', NULL),
(72, 3, 270, 18, 5, 4, 600, 'Dokončení oprav na budově šaten\r\n===============================\r\n\r\n- kontrola a dotažení uvolněných zásuvek\r\n- výměna světla v koupelně (chyběl na něm skleněný kryt žárovky) za nové\r\n\r\nBudova \"PRIOR\"\r\n==============\r\n\r\n- pojmenováni rozvaděče po dovodě s mistrem elektro na: \"RS1 PRIOR\"\r\n- vytvoření nového štítku rozvaděče včetně napěťové soustavy\r\n- dohledání odkud je napájen tento rozvaděč a vytisknutí a nalepení popisku dovnitř skříně\r\n\r\n\r\nVyčistění rozvaděče (', 4, '2026-07-17 13:01:35', NULL),
(73, 1, 415, 21, 0, 1, 240, 'fghfghgfhghd', 1, '2026-09-11 22:51:50', NULL),
(74, 1, 415, 21, 0, 1, -240, 'fgbnfgf', 1, '2026-09-11 22:52:17', NULL);
