INSERT INTO `work_orders` (`id`, `company_id`, `external_number`, `title`, `description`, `wo_due_date`, `source`, `requested_by`, `contact_person`, `priority`, `estimated_hours`, `status`, `is_system`, `created_by_user_id`, `created_at`, `closed_at`, `internal_number`, `contact_id`, `price_per_hour`, `price_per_km`, `year`) VALUES
(1, 1, 'dd12458', 'rozjetí Bo na bo.krteczek.cz', 'Rozjet to, opravit chyby, rozjet to :)', NULL, 'personal', 'Petr', '', 'high', NULL, 'done', 0, 1, '2026-04-14 00:12:42', '2026-04-17 01:14:03', 1, NULL, 1000, 12, 2026),
(2, 2, NULL, 'Režie firmy', '\n          **Režijní práce** jsou běžné práce vykonávané pro fungování samotné firmy.\n\n          Například čas strávený vytvořením účtu v našem systému a seznámení se s ním,\n          se dá považovat za režijní náklad firmy.\n\n          K téhle zakázce je systémem vytvořeno několik prvních úkolů pro seznámení se s naším systémem.\n\n        ', NULL, 'email', NULL, NULL, 'normal', NULL, 'in_progress', 0, 2, '2026-04-14 01:32:19', NULL, 1, NULL, 0, 0, 2026),
(3, 1, NULL, 'Žijeme na planetě hmyzu', 'Žijeme na planetě hmyzu, který je majitelem planety a zřejmě řídí a vysává lidi. Však to znáte, komáři, mouchy.. mravenci... znepříjemní vám to hodně, když chtějí. Samozřejmě, nesmí se o tom mluvit, protože by se lidé zbláznili, poté, co by dlouho nevěřili. Leč... kniha Mariborská hypnóza, která vyhrála Magnesia litera, je přesně o tom. Tedy.. o mouchách, aspoň kam se to doposlouchal. A poslouchat ji v audio verzi je za trest, ještě navíc v noci, to je horor. Čapku, Havlíčku, Boženo.. vraťte se. Sion-fašisté, aktivní pomohači hmyzí civiliziace, nám unesli již i  literaturu. Film už dávno.\r\nBuď začneme napodobovat hmyz (třeba včely či mravenci se doslova nabízejí), těch, kterých je miliard krát víc, než nás, aspoň částečně, anebo bude naše civilizace znovu, již poněkolikáté, smetena. Již se hmyz adaptoval na vaše nové (spike) syntetické proteiny, které vám implantovala satanská vědecká sekta pomocí tzv. očkování proti tzv. covidu, co myslíte? Pro koho se ta výměna vlastně děla? Pro lidi až na posledním místě. Lidé jsou dělníci, námezní otroci. A jejich využitelnost pomalu končí. To, co zatím zvládlo tisíc lidí starého typu, zvládne jeden člověk s upgradovaným vědomím a schopnostmi, přibližně 50-100x geneticky poupravený (očkovaný).', NULL, 'email', '', '', 'normal', NULL, 'cancelled', 0, 1, '2026-04-20 13:37:27', '2026-04-20 13:37:36', 2, NULL, 1000, 100, 2026),
(4, 1, NULL, 'Žijeme na planetě hmyzu 2', 'Žijeme na planetě hmyzu, který je majitelem planety a zřejmě řídí a vysává lidi. Však to znáte, komáři, mouchy.. mravenci... znepříjemní vám to hodně, když chtějí. Samozřejmě, nesmí se o tom mluvit, protože by se lidé zbláznili, poté, co by dlouho nevěřili. Leč... kniha Mariborská hypnóza, která vyhrála Magnesia litera, je přesně o tom. Tedy.. o mouchách, aspoň kam se to doposlouchal. A poslouchat ji v audio verzi je za trest, ještě navíc v noci, to je horor. Čapku, Havlíčku, Boženo.. vraťte se. Sion-fašisté, aktivní pomohači hmyzí civiliziace, nám unesli již i  literaturu. Film už dávno.\r\nBuď začneme napodobovat hmyz (třeba včely či mravenci se doslova nabízejí), těch, kterých je miliard krát víc, než nás, aspoň částečně, anebo bude naše civilizace znovu, již poněkolikáté, smetena. Již se hmyz adaptoval na vaše nové (spike) syntetické proteiny, které vám implantovala satanská vědecká sekta pomocí tzv. očkování proti tzv. covidu, co myslíte? Pro koho se ta výměna vlastně děla? Pro lidi až na posledním místě. Lidé jsou dělníci, námezní otroci. A jejich využitelnost pomalu končí. To, co zatím zvládlo tisíc lidí starého typu, zvládne jeden člověk s upgradovaným vědomím a schopnostmi, přibližně 50-100x geneticky poupravený (očkovaný).', NULL, 'email', '', '', 'low', 0.00, 'new', 0, 1, '2026-04-20 13:38:25', NULL, 3, 1, 1000, 20, 2026),
(5, 1, NULL, 'Zahrada', 'Věci doma na zahradě', NULL, 'personal', 'Ja', '', 'normal', NULL, 'new', 0, 1, '2026-04-23 17:09:15', NULL, 4, NULL, 0, 0, 2026),
(6, 3, NULL, 'Režie firmy', '\nVítejte v Bó systému.\n---------------------\n\n**Režijní práce** jsou běžné práce vykonávané pro fungování samotné firmy.\n\nNapříklad čas strávený vytvořením účtu v našem systému a seznámení se s ním,\nse dá považovat za režijní náklad firmy.\n\nK téhle zakázce je systémem vytvořeno několik prvních úkolů pro seznámení se s naším systémem.\n\n            ', NULL, 'email', NULL, NULL, 'normal', NULL, 'done', 0, 4, '2026-06-03 13:24:01', '2026-06-05 13:39:39', 1, NULL, 0, 0, 2026),
