(14, 3, NULL, 'Výtok č.4', 'Vypíná čerpadlo 14FM 401\r\n\r\nZměřit odběry, izolační stav. Zjistit co to píše. Odhalit co se děje.', NULL, 'email', '', '', 'low', 0.00, 'done', 0, 4, '2026-06-16 07:10:50', '2026-06-18 13:18:25', 9, NULL, 0, 0, 2026),
(15, 3, NULL, 'Nesvítí venkovní reflektor. Vodárna 1', 'Na stěně vodárny 1, směrem  k Olze, nad zásobníkem stlačeného vzduchu, nesvítí led reflektor.', '2026-06-19', 'phone', 'Dispečer vodárny 1', 'Dispečink', 'normal', 0.00, 'done', 0, 4, '2026-06-18 12:53:26', '2026-06-18 13:14:55', 10, NULL, 0, 0, 2026),
